-- 473: Original BrillaPrep Cambridge A-Level Biology (9700) Ecology and Nutrient Cycles multiple-choice questions (part 1) (batch alevel-bio-sprint2-001).
-- Curriculum-aligned practice content; not official Cambridge International or WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE _migration_473_expected (id TEXT PRIMARY KEY, topic_id TEXT, subject_id TEXT, exam_type_id TEXT, paper_type_id TEXT, past_paper_id TEXT, question_text TEXT, question_type TEXT, round_type TEXT, options TEXT, correct_answer TEXT, explanation TEXT, difficulty TEXT, points INTEGER, marks INTEGER, time_limit INTEGER, question_number INTEGER, section TEXT, is_compulsory INTEGER, image_url TEXT, syllabus_topic_id TEXT, command_word TEXT, assessment_objective TEXT, source_paper_code TEXT, source_question_number TEXT, exam_board_id TEXT);
INSERT INTO _migration_473_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_ecology_s2_001', 'topic_alevel_bio_ecology', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In the nitrogen cycle, which process is carried out by Rhizobium bacteria living in the root nodules of legumes such as cowpea and groundnut?', 'multiple_choice', NULL, '["A. Conversion of atmospheric nitrogen gas into ammonia (nitrogen fixation)","B. Oxidation of ammonium ions to nitrite ions","C. Oxidation of nitrite ions to nitrate ions","D. Conversion of nitrate ions into nitrogen gas"]', 'A', 'Rhizobium is a mutualistic nitrogen-fixing bacterium: inside root nodules it uses the enzyme nitrogenase to reduce inert atmospheric nitrogen gas to ammonia, which the host plant uses to make amino acids, while the plant supplies the bacteria with carbohydrates. Oxidising ammonium to nitrite and nitrite to nitrate is nitrification (carried out by Nitrosomonas and Nitrobacter), and converting nitrate back to nitrogen gas is denitrification, carried out by bacteria such as Pseudomonas in anaerobic, waterlogged soils. Therefore the correct answer is A: Conversion of atmospheric nitrogen gas into ammonia (nitrogen fixation).', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_ecology_s2_002', 'topic_alevel_bio_ecology', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In the food chain grass → grasshopper → lizard → hawk, which organism is the secondary consumer?', 'multiple_choice', NULL, '["A. Grasshopper","B. Lizard","C. Hawk","D. Grass"]', 'B', 'Trophic levels count from the producer: grass (producer) is eaten by the grasshopper (primary consumer, a herbivore), which is eaten by the lizard (secondary consumer, the first carnivore), which is eaten by the hawk (tertiary consumer). A common error is to label the grasshopper as the secondary consumer by counting the producer as the first consumer, but consumers are numbered only from the herbivore level. Therefore the correct answer is B: Lizard.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_ecology_s2_003', 'topic_alevel_bio_ecology', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'What name is given to all the populations of different species living and interacting in the same area at the same time?', 'multiple_choice', NULL, '["A. A population","B. An ecosystem","C. A community","D. A habitat"]', 'C', 'A community is all the biotic components — every population of every species living and interacting in one area at one time. A population is the members of a single species only; an ecosystem includes the community together with the non-living (abiotic) environment; a habitat is simply the place where an organism lives, not the set of organisms itself. Therefore the correct answer is C: A community.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_ecology_s2_004', 'topic_alevel_bio_ecology', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which equation correctly relates gross primary productivity (GPP), respiration losses (R) and net primary productivity (NPP)?', 'multiple_choice', NULL, '["A. NPP = GPP + R","B. GPP = NPP − R","C. NPP = R − GPP","D. NPP = GPP − R"]', 'D', 'Gross primary productivity is the total chemical energy that producers fix in photosynthesis. Producers respire, releasing some of that energy as heat, so the energy left available for growth, reproduction and transfer to herbivores is net primary productivity: NPP = GPP − R. Adding respiration back, or rearranging the equation so that GPP loses NPP, confuses the direction of the relationship — respiration is a loss from GPP, never an addition to NPP. Therefore the correct answer is D: NPP = GPP − R.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_ecology_s2_005', 'topic_alevel_bio_ecology', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which statement best explains why only about 10% of the energy at one trophic level is typically transferred to the next?', 'multiple_choice', NULL, '["A. Most of the energy is lost as heat from respiration, and some remains in parts that are not eaten or cannot be digested, or is lost in excretory products","B. Decomposers directly absorb 90% of the energy before herbivores can feed","C. Predators deliberately consume only about 10% of the prey population","D. About 90% of the energy is destroyed during digestion inside the consumer"]', 'A', 'Energy transfer is inefficient because consumers use much of the energy they assimilate in respiration, which is lost as heat that cannot re-enter the food chain, while energy in bones, cellulose and other indigestible or uneaten material, and in urea and faeces, passes to decomposers rather than to the next trophic level. Energy is never destroyed — that would violate the conservation of energy — and the 10% figure is an ecological average, not a behavioural rule about how much predators choose to eat. Therefore the correct answer is A: Most of the energy is lost as heat from respiration, and some remains in parts that are not eaten or cannot be digested, or is lost in excretory products.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_ecology_s2_006', 'topic_alevel_bio_ecology', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which sequence correctly describes nitrification in the soil?', 'multiple_choice', NULL, '["A. Nitrobacter oxidises ammonium ions to nitrite ions, then Nitrosomonas oxidises nitrite ions to nitrate ions","B. Nitrosomonas oxidises ammonium ions to nitrite ions, then Nitrobacter oxidises nitrite ions to nitrate ions","C. Rhizobium oxidises ammonium ions directly to nitrate ions in root nodules","D. Nitrosomonas converts nitrogen gas to ammonium ions, then Nitrobacter converts ammonium ions to nitrate ions"]', 'B', 'Nitrification is a two-step oxidation carried out by different soil bacteria: Nitrosomonas oxidises ammonium ions (NH4+) to nitrite ions (NO2−), then Nitrobacter oxidises nitrite ions to nitrate ions (NO3−), the form most plants absorb. Swapping the two genera or the two ions confuses the steps. Rhizobium fixes atmospheric nitrogen gas in legume root nodules and plays no part in nitrification, and the conversion of nitrogen gas to ammonium ions is nitrogen fixation, not the first step of nitrification. Therefore the correct answer is B: Nitrosomonas oxidises ammonium ions to nitrite ions, then Nitrobacter oxidises nitrite ions to nitrate ions.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Describe', 'AO1', NULL, NULL, 'board_cambridge');
CREATE TABLE _migration_473_expected_parts (id TEXT PRIMARY KEY, question_id TEXT NOT NULL, part_label TEXT NOT NULL, part_text TEXT NOT NULL, marks INTEGER NOT NULL, correct_answer TEXT NOT NULL, display_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS _migration_473_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_473_guard;
INSERT INTO _migration_473_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_473_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_473_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'alevel-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_473_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'alevel-bio-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/', 0, 1 FROM _migration_473_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
DELETE FROM _migration_473_guard;
INSERT INTO _migration_473_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_473_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_473_expected e ON e.id = r.question_id WHERE r.batch_id IS 'alevel-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_473_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_473_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 0 THEN 1 ELSE 0 END;
